421	            topics = "payment-processing-topic",
422	            groupId = "payment-processing-group",
423	            containerFactory = "paymentEventKafkaListenerContainerFactory"
424	    )
425	    @Transactional
426	    public void handlePaymentEvent(
427	            @Payload Xbf54Event event,
428	            @Header(KafkaHeaders.RECEIVED_PARTITION) int partition,
429	            @Header(KafkaHeaders.OFFSET) long offset,
430	            Acknowledgment acknowledgment) {
431	
432	        Instant start = Instant.now();
433	
434	        try {
435	            log.info("결제 처리 이벤트 수신: 주문ID={}, 이벤트ID={}, 파티션={}, 오프셋={}",
436	                    event.getOrderId(), event.getEventId(), partition, offset);
437	
438	
439	            if (isPaymentAlreadyProcessed(event.getOrderId())) {
440	                log.warn("이미 처리된 결제 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
441	                acknowledgment.acknowledge();
442	                return;
443	            }
444	
445	
446	            Xdg64 order = orderRepository.findById(event.getOrderId())
447	                    .orElseThrow(() -> new IllegalArgumentException(
448	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
449	
450	
451	            Xrd81 user = userQueryService.findByEmail(event.getUserEmail());
452	
453	
454	            if (!order.getUser().getId().equals(user.getId())) {
455	                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
456	                        event.getOrderId(), order.getUser().getId(), user.getId());
457	                throw new Xbf54Exception(null, "주문과 사용자 정보가 일치하지 않습니다.");
458	            }
459	
460	
461	            Xbf54 payment = paymentCommandService.processPayment(order, user, event.getPaymentRequest());
462	
463	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 결제상태={}",
464	                    event.getOrderId(), payment.getId(), payment.getStatus());
465	
466	
467	            acknowledgment.acknowledge();
468	
469	
470	            Instant end = Instant.now();
471	            Duration duration = Duration.between(start, end);
472	            log.info("결제 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
473	
474	        } catch (Xbf54Exception e) {
475	            log.error("결제 처리 실패 (Xbf54Exception): 주문ID={}, 오류={}",
476	                    event.getOrderId(), e.getMessage(), e);
477	            handlePaymentFailure(event, e, acknowledgment);
478	
479	        } catch (Exception e) {
480	            log.error("결제 처리 중 예상치 못한 오류: 주문ID={}, 오류={}",
481	                    event.getOrderId(), e.getMessage(), e);
482	            handlePaymentFailure(event, e, acknowledgment);
483	        }
484	    }
