495	    public void handlePaymentRetryEvent(
496	            @Payload Xbf54Event event,
497	            Acknowledgment acknowledgment) {
498	
499	        try {
500	            log.info("결제 재시도 처리: 주문ID={}, 재시도횟수={}",
501	                    event.getOrderId(), event.getRetryCount());
502	
503	
504	            if (event.isMaxRetryExceeded()) {
505	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
506	                        event.getOrderId(), event.getRetryCount());
507	                acknowledgment.acknowledge();
508	                return;
509	            }
510	
511	
512	            if (isPaymentAlreadyProcessed(event.getOrderId())) {
513	                log.info("재시도 중 결제 완료 확인: 주문ID={}", event.getOrderId());
514	                acknowledgment.acknowledge();
515	                return;
516	            }
517	
518	
519	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
520	
521	
522	            handlePaymentEvent(event, 0, 0, acknowledgment);
523	
524	        } catch (InterruptedException e) {
525	            Thread.currentThread().interrupt();
526	            log.error("결제 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
527	            acknowledgment.acknowledge();
528	        } catch (Exception e) {
529	            log.error("결제 재시도 처리 중 오류: 주문ID={}, 오류={}",
530	                    event.getOrderId(), e.getMessage(), e);
531	            acknowledgment.acknowledge();
532	        }
533	    }
