538	    private boolean isPaymentAlreadyProcessed(Long orderId) {
539	        try {
540	            Optional<Xbf54> existingPayment = paymentRepository.findByOrder_Id(orderId);
541	
542	            if (existingPayment.isPresent()) {
543	                Xbf54 payment = existingPayment.get();
544	                log.info("기존 결제 발견: 주문ID={}, 결제ID={}, 결제상태={}",
545	                        orderId, payment.getId(), payment.getStatus());
546	
547	
548	                return payment.isSuccess();
549	            }
550	
551	            return false;
552	        } catch (Exception e) {
553	            log.error("결제 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
554	            return false;
555	        }
556	    }
