561	    private void handlePaymentFailure(Xbf54Event event, Exception error, Acknowledgment acknowledgment) {
562	        try {
563	
564	            if (isRetryableError(error)) {
565	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
566	                paymentEventProducer.sendPaymentRetryEvent(event);
567	            } else {
568	                log.error("재시도 불가능한 오류로 결제 실패 처리: 주문ID={}, 오류={}",
569	                        event.getOrderId(), error.getMessage());
570	
571	            }
572	
573	            acknowledgment.acknowledge();
574	
575	        } catch (Exception e) {
576	            log.error("결제 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
577	            acknowledgment.acknowledge();
578	        }
579	    }
580	
581	
582	
583	
584	    private boolean isRetryableError(Exception error) {
585	
586	        return !(error instanceof IllegalArgumentException) &&
587	                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
588	    }
