338	                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
339	                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
340	                } else {
