 74	    public String getAccessToken() {
 75	        Instant start = Instant.now();
 76	        String url = BASE_URL + TOKEN_URL;
 77	
 78	        log.info("PortOne API 토큰 발급 요청 시작");
 79	
 80	
 81	        Map<String, String> requestBody = new HashMap<>();
 82	        requestBody.put("imp_key", impKey);
 83	        requestBody.put("imp_secret", impSecret);
 84	
 85	
 86	        HttpHeaders headers = new HttpHeaders();
 87	        headers.setContentType(MediaType.APPLICATION_JSON);
 88	
 89	        try {
 90	
 91	            ObjectMapper objectMapper = new ObjectMapper();
 92	            String jsonBody = objectMapper.writeValueAsString(requestBody);
 93	
 94	            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
 95	
 96	            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);
 97	
 98	            if (response.getStatusCode() == HttpStatus.OK) {
 99	                Map<String, Object> responseBody = response.getBody();
100	                Map<String, Object> responseContent = (Map<String, Object>) responseBody.get("response");
101	
102	                if (responseContent == null || responseContent.get("access_token") == null) {
103	                    throw new Xbf54ApiException("토큰 발급 응답에서 access_token을 찾을 수 없습니다.");
104	                }
105	
106	                String accessToken = (String) responseContent.get("access_token");
107	                log.info("PortOne API 토큰 발급 성공: {}", accessToken.substring(0, Math.min(10, accessToken.length())) + "...");
108	
109	
110	                Instant end = Instant.now();
111	                Duration duration = Duration.between(start, end);
112	                log.debug("PortOne API 토큰 발급 처리 시간: {}ms", duration.toMillis());
113	
114	                return accessToken;
115	            } else {
116	                log.error("PortOne API 토큰 발급 실패: HTTP 상태 코드 {}", response.getStatusCodeValue());
117	                throw new Xbf54ApiException("토큰 발급 실패: HTTP 상태 코드 " + response.getStatusCodeValue());
118	            }
119	        } catch (Xbf54Exception e) {
120	            throw e;
121	        } catch (RestClientException e) {
122	            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
123	            throw new Xbf54ApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
124	        } catch (Exception e) {
125	            log.error("PortOne API 토큰 발급 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
126	            throw new Xbf54Exception(Xbf54ErrorCode.TOKEN_ISSUANCE_FAILED, e);
127	        }
128	    }
