328	    public void updateWebSocketConnectionTTL(String email) {
329	        try {
330	            if (email != null) {
331	                String redisKey = REDIS_KEY_PREFIX + email;
332	
333	
334	                Long remainingTime = redisTemplate.getExpire(redisKey, TimeUnit.SECONDS);
335	
336	
337	                if (remainingTime != null && remainingTime <= 600) {
338	                    redisTemplate.expire(redisKey, REDIS_TTL_MINUTES, TimeUnit.MINUTES);
339	                    log.debug("Redis TTL 갱신: 사용자={}, 남은TTL={}초", email, remainingTime);
340	                } else {
341	                    log.debug("TTL 연장 불필요: 사용자={}, 남은TTL={}초", email, remainingTime);
342	                }
343	            }
344	        } catch (Exception e) {
345	            log.error("WebSocket 연결 TTL 갱신 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
